        {"id": "INV-act-003", "text": "created_accounts is cleared when the outermost transaction commits or rolls back (snapshots becomes empty)."}
      ],
      "functions": [
        {"id": "FN-act-001", "signature": "mark_account_created(state: State, address: Address) -> None", "description": "Mark an account as created in the current transaction for EIP-6780 and storage original tracking."}
      ],
      "state_variables": []
    }
